@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments</PageTitle>

<h2 class="mb-4">Shipments</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking # or destination..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            <option value="Pending">Pending</option>
            <option value="PickedUp">Picked Up</option>
            <option value="InTransit">In Transit</option>
            <option value="OutForDelivery">Out for Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Cancelled">Cancelled</option>
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-3">
                <div class="col-md-3">
                    <label class="form-label">Tracking #</label>
                    <input class="form-control" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Customer Email</label>
                    <input class="form-control" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Notes</label>
                    <input class="form-control" @bind="newShipment.Notes" />
                </div>
                <div class="col-12">
                    <button class="btn btn-success me-2" @onclick="CreateShipment">Save</button>
                    <button class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
                    @if (!string.IsNullOrEmpty(createError))
                    {
                        <span class="text-danger ms-3">@createError</span>
                    }
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p class="text-muted">No shipments match your search.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Created</th>
                    <th>Est. Delivery</th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span></td>
                        <td>@s.CreatedDate.ToString("yyyy-MM-dd")</td>
                        <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
                        <td>@(s.CustomerEmail ?? "—")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto" @bind="editStatus">
                                    <option value="Pending">Pending</option>
                                    <option value="PickedUp">Picked Up</option>
                                    <option value="InTransit">In Transit</option>
                                    <option value="OutForDelivery">Out for Delivery</option>
                                    <option value="Delivered">Delivered</option>
                                    <option value="Cancelled">Cancelled</option>
                                </select>
                                <button class="btn btn-sm btn-success ms-1" @onclick="() => SaveStatus(s)">Save</button>
                                <button class="btn btn-sm btn-secondary ms-1" @onclick="CancelEdit">Cancel</button>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update Status</button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string searchTerm = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { Status = "Pending" };
    private string? createError;
    private int? editingId;
    private string editStatus = "";

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(searchTerm) ||
             s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
             s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        createError = null;
        newShipment = new() { Status = "Pending" };
    }

    private async Task CreateShipment()
    {
        createError = null;
        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
            string.IsNullOrWhiteSpace(newShipment.Origin) ||
            string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Tracking #, origin, and destination are required.";
            return;
        }
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments!.Insert(0, created);
            CancelCreate();
        }
        catch (Exception ex)
        {
            createError = $"Error: {ex.Message}";
        }
    }

    private void StartEdit(ShipmentDto s)
    {
        editingId = s.Id;
        editStatus = s.Status;
    }

    private void CancelEdit() => editingId = null;

    private async Task SaveStatus(ShipmentDto s)
    {
        s.Status = editStatus;
        await ShipmentService.UpdateShipmentAsync(s);
        editingId = null;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-10001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning" role="alert">
        @errorMessage
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span></dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <strong>@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</strong>
                                @if (shipment.Status != "Delivered" && shipment.Status != "Cancelled")
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                                    if (daysLeft > 0)
                                    {
                                        <span class="text-muted ms-2">(@daysLeft day(s) remaining)</span>
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        <span class="text-success ms-2">(Arriving today!)</span>
                                    }
                                    else
                                    {
                                        <span class="text-danger ms-2">(Delayed)</span>
                                    }
                                }
                            }
                            else
                            {
                                <span class="text-muted">Not available</span>
                            }
                        </dd>
                        @if (!string.IsNullOrEmpty(shipment.Notes))
                        {
                            <dt>Notes</dt>
                            <dd>@shipment.Notes</dd>
                        }
                    </dl>
                </div>
            </div>

            <!-- Progress bar -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercent(shipment.Status)%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @FormatStatus(shipment.Status)
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task TrackShipment()
    {
        errorMessage = null;
        shipment = null;

        if (string.IsNullOrWhiteSpace(trackingNumber))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        isLoading = true;
        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (shipment is null)
            {
                errorMessage = $"No shipment found with tracking number \"{trackingNumber.Trim()}\".";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error looking up shipment: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        "Cancelled" => 100,
        _ => 0
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Cancelled" => "bg-danger",
        "Delivered" => "bg-success",
        _ => "bg-primary"
    };
}

