@if (errorMessage is not null)
{
    <div class="alert alert-warning" role="alert">
        @errorMessage
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span></dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <strong>@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</strong>
                                @if (shipment.Status != "Delivered" && shipment.Status != "Cancelled")
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                                    if (daysLeft > 0)
                                    {
                                        <span class="text-muted ms-2">(@daysLeft day(s) remaining)</span>
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        <span class="text-success ms-2">(Arriving today!)</span>
                                    }
                                    else
                                    {
                                        <span class="text-danger ms-2">(Delayed)</span>
                                    }
                                }
                            }
                            else
                            {
                                <span class="text-muted">Not available</span>
                            }
                        </dd>
