### 8. API Endpoints (Server Program.cs)

Add the following API endpoints to the server `Program.cs` — insert them BEFORE `app.Run();` and after `app.MapAdditionalIdentityEndpoints();`:

```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("", async (ShipmentTracker.Client.IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()));

shipments.MapGet("track/{trackingNumber}", async (string trackingNumber, ShipmentTracker.Client.IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

shipments.MapPost("", async (ShipmentTracker.Client.ShipmentDto dto, ShipmentTracker.Client.IShipmentService service) =>
{
    var created = await service.CreateShipmentAsync(dto);
    return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
});

shipments.MapPut("{id:int}", async (int id, ShipmentTracker.Client.ShipmentDto dto, ShipmentTracker.Client.IShipmentService service) =>
{
    dto.Id = id;
    var updated = await service.UpdateShipmentAsync(dto);
    return Results.Ok(updated);
});
```

